head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.onpageload = function() {
	var data2 = [];
	for (var i = 0; i < 10; i++) {
		for (var j = 0; j < 4; j++) {
			data2.push(i * 4 + j);
		}
	}
	dataList2.setData(data2);
	window.common = {};
	common.nextTabFunction = function(compId) {
		window.dest = common.findNextFocusedComp(compId);
		while (dest != undefined) {
			if (dest.getDisabled() !== true && dest.getReadOnly() !== true) {
				dest.focus();
				break;
			}
			dest = common.findNextFocusedComp(dest.id);
		}
	}
	common.findNextFocusedComp = function(compId) {
		window.dest = "";
		window.source = scwin.__getObj(compId);
		window.idPrefix = source.scope_id == null ? "" : source.scope_id + "_"
		switch (source.getOriginalID()) {
			case "input1":
				dest = "input2";
				break;
			case "input2":
				dest = "selectbox2";
				break;
		}
		return WebSquare.util.getComponentById(dest, source.scope_id);
	}
};
